let getState,change,selectedMark={dots:-1,scars:-1};
const $=s=>document.querySelector(s);
const select=(key,label,options)=>`<label class="advanced-field"><span>${label}</span><select data-setting="${key}">${options.map(([value,name])=>`<option value="${value}">${name}</option>`).join('')}</select></label>`;
const color=(key,label)=>`<label class="advanced-field color-field"><span>${label}</span><input type="color" data-setting="${key}" aria-label="${label}"></label>`;
const check=(key,label)=>`<label class="advanced-check"><input type="checkbox" data-setting="${key}">${label}</label>`;
const range=(key,label)=>{const[min,max]=numberRules[key];return `<label class="advanced-field range-field"><span>${label}<output data-output="${key}"></output></span><input type="range" data-setting="${key}" min="${min}" max="${max}" step="${key==='outlineWidth'?'.001':'.01'}" aria-label="${label}"></label>`;};
const details=(title,body)=>`<details class="advanced-section"><summary>${title}<span>＋</span></summary><div class="advanced-body">${body}</div></details>`;
